implementations.python:
def first_index(values, target):
    # Invariant: every index before i differs from target.
    for i, value in enumerate(values):
        if value == target:
            return i
    return -1

assert first_index([8, 3, 5, 3], 3) == 1
assert first_index([], 3) == -1

implementations.cpp:
#include <vector>
#include <cassert>
#include <cstddef>
using namespace std;
// Educational inputs have at most 10,000 elements, so int holds each index.
int first_index(const vector<int>& values, int target) {
    for (size_t i = 0; i < values.size(); ++i)
        if (values[i] == target) return static_cast<int>(i);
    return -1;
}
int main() {
    assert(first_index({8, 3, 5, 3}, 3) == 1);
    assert(first_index({}, 3) == -1);
}

implementations.java:
class FirstMatch {
    static int firstIndex(int[] values, int target) {
        for (int i = 0; i < values.length; i++)
            if (values[i] == target) return i;
        return -1;
    }
    public static void main(String[] args) {
        if (firstIndex(new int[]{8, 3, 5, 3}, 3) != 1)
            throw new AssertionError("first occurrence");
        System.out.println(firstIndex(new int[]{}, 3));
    }
}

